#!/usr/bin/env node
/**
 * einstellungen.mjs — Einstellungen des claude-workflow-kit über eine lokale Oberfläche
 * pflegen (Plan #674, fachlich #671).
 *
 * Eine einzelne Datei, die als Download ausgeliefert wird und in kein Projekt gehört: Sie
 * arbeitet über alle Kit-Projekte unter einem Ordner. Darum hat sie keine Nachbardateien,
 * aus denen sie importieren könnte, und trägt Schema und Regeln selbst.
 *
 * Dieser Stand (Issue #676) ist der Kern ohne Server: prüfen gegen das eingebettete Schema
 * und die Regeln über mehrere Felder, Team- und persönliche Ebene, und ein Schreiber, der
 * nur die geänderten Werte anfasst. Alles hier ist rein und exportiert.
 *
 * Nutzung:
 *   node einstellungen.mjs --version
 *   node einstellungen.mjs --help
 */

import { realpathSync } from "node:fs";
import { fileURLToPath } from "node:url";

// Wird von tools/sync-blobs.mjs gestempelt — nie von Hand setzen (Issue #171).
const KIT_VERSION = "1.53.1";

// Das Schema aus templates/workflow.config.schema.json, eingebettet von tools/sync-blobs.mjs
// (Plan #674 E2). Base64 wie die Blobs in install.mjs: Der Text darf Anführungszeichen,
// Backticks und Zeilenumbrüche tragen, ohne dass hier etwas zu maskieren wäre.
const SCHEMA_B64 = "";

export const SCHEMA = JSON.parse(Buffer.from(SCHEMA_B64, "base64").toString("utf-8") || "{}");

// ============================================================
// Prüfung gegen das Schema (Plan #674 E4, E5)
// ============================================================

/** Genau die Schlüsselwörter, die das Schema benutzt — ein Test hält beide gleich. */
export const SCHLUESSELWOERTER = [
  "type", "enum", "pattern", "oneOf", "not", "required", "minItems", "minProperties",
  "additionalProperties", "properties", "items", "minLength", "minimum", "exclusiveMinimum", "uniqueItems",
];

const istObjekt = (w) => w !== null && typeof w === "object" && !Array.isArray(w);

function typName(wert) {
  if (wert === null) return "null";
  if (Array.isArray(wert)) return "array";
  if (Number.isInteger(wert)) return "integer";
  return typeof wert;
}

function passtTyp(wert, erwartet) {
  const liste = Array.isArray(erwartet) ? erwartet : [erwartet];
  const ist = typName(wert);
  return liste.some((t) => t === ist || (t === "number" && ist === "integer"));
}

const pfadVon = (basis, schluessel) => (basis ? `${basis}.${schluessel}` : String(schluessel));

function befund(pfad, grund, art = "fehler") {
  return { pfad, art, grund };
}

function pruefeText(wert, schema, pfad, out) {
  if (schema.pattern !== undefined && !new RegExp(schema.pattern, "u").test(wert)) out.push(befund(pfad, `passt nicht auf das Muster ${schema.pattern}`));
  if (schema.minLength !== undefined && wert.length < schema.minLength) out.push(befund(pfad, `muss mindestens ${schema.minLength} Zeichen lang sein`));
}

function pruefeZahl(wert, schema, pfad, out) {
  if (schema.minimum !== undefined && wert < schema.minimum) out.push(befund(pfad, `muss mindestens ${schema.minimum} sein`));
  if (schema.exclusiveMinimum !== undefined && wert <= schema.exclusiveMinimum) out.push(befund(pfad, `muss größer als ${schema.exclusiveMinimum} sein`));
}

/** Die Prüfungen, die sich auf einen einzelnen Wert beziehen; `false` bei falschem Typ. */
function pruefeSkalar(wert, schema, pfad, out) {
  if (schema.type !== undefined && !passtTyp(wert, schema.type)) {
    out.push(befund(pfad, `muss vom Typ ${[].concat(schema.type).join(" oder ")} sein, ist ${typName(wert)}`));
    return false;
  }
  if (Array.isArray(schema.enum) && !schema.enum.some((e) => JSON.stringify(e) === JSON.stringify(wert))) {
    out.push(befund(pfad, `muss einer von ${schema.enum.map((e) => JSON.stringify(e)).join(", ")} sein`));
  }
  if (typeof wert === "string") pruefeText(wert, schema, pfad, out);
  if (typeof wert === "number") pruefeZahl(wert, schema, pfad, out);
  return true;
}

function pruefeListe(wert, schema, pfad, out) {
  if (schema.minItems !== undefined && wert.length < schema.minItems) out.push(befund(pfad, `braucht mindestens ${schema.minItems} Einträge`));
  if (schema.uniqueItems === true && new Set(wert.map((w) => JSON.stringify(w))).size !== wert.length) out.push(befund(pfad, "nennt einen Eintrag doppelt"));
  if (istObjekt(schema.items)) wert.forEach((eintrag, i) => pruefeKnoten(eintrag, schema.items, `${pfad}[${i}]`, out));
}

function pruefeObjekt(wert, schema, pfad, out) {
  for (const feld of schema.required ?? []) {
    if (!(feld in wert)) out.push(befund(pfadVon(pfad, feld), "fehlt"));
  }
  if (schema.minProperties !== undefined && Object.keys(wert).length < schema.minProperties) out.push(befund(pfad || "(Wurzel)", `braucht mindestens ${schema.minProperties} Einträge`));
  const bekannt = schema.properties ?? {};
  for (const [feld, kind] of Object.entries(wert)) {
    const p = pfadVon(pfad, feld);
    if (feld in bekannt) pruefeKnoten(kind, bekannt[feld], p, out);
    else if (schema.additionalProperties === false) out.push(befund(p, "ist dieser Oberfläche unbekannt — der Wert bleibt beim Speichern erhalten", "unbekannt"));
    else if (istObjekt(schema.additionalProperties)) pruefeKnoten(kind, schema.additionalProperties, p, out);
  }
}

/** Nur die Fehler eines Teilschemas — für oneOf und not, wo Warnungen nicht zählen. */
function nurFehler(wert, schema, pfad) {
  const out = [];
  pruefeKnoten(wert, schema, pfad, out);
  return out.filter((b) => b.art === "fehler");
}

function pruefeVerknuepfungen(wert, schema, pfad, out) {
  if (Array.isArray(schema.oneOf)) {
    const treffer = schema.oneOf.filter((teil) => nurFehler(wert, teil, pfad).length === 0).length;
    if (treffer !== 1) out.push(befund(pfad || "(Wurzel)", treffer === 0 ? "passt auf keine der erlaubten Formen" : "passt auf mehr als eine der erlaubten Formen — genau eine ist erlaubt"));
  }
  if (istObjekt(schema.not) && nurFehler(wert, schema.not, pfad).length === 0) {
    out.push(befund(pfad || "(Wurzel)", "hat eine ausgeschlossene Form"));
  }
}

function pruefeKnoten(wert, schema, pfad, out) {
  if (!istObjekt(schema)) return;
  if (!pruefeSkalar(wert, schema, pfad, out)) return;
  if (Array.isArray(wert)) pruefeListe(wert, schema, pfad, out);
  else if (istObjekt(wert)) pruefeObjekt(wert, schema, pfad, out);
  pruefeVerknuepfungen(wert, schema, pfad, out);
}

/**
 * Prüft einen Wert gegen ein Schema. Liefert `[{ pfad, art, grund }]` mit `art` aus
 * `fehler` oder `unbekannt`; `unbekannt` nur für Felder, die `additionalProperties: false`
 * ausschließt (Plan #674 E5).
 */
export function pruefeSchema(wert, schema = SCHEMA) {
  const out = [];
  pruefeKnoten(wert, schema, "", out);
  return out;
}

// ============================================================
// Regeln über mehrere Felder (Plan #674 E18)
// ============================================================
//
// Das Schema kennt nur das Reviewer-Paar als Regel über zwei Felder. Diese Regeln brechen
// heute erst im Lauf; die Oberfläche soll sie vor dem Speichern nennen.

// SYNC: Laufzeitregel in kit/board.mjs, validateReviewStufen — rollen.length gleich reviewer.
function regelRollenzahl(config) {
  const out = [];
  for (const [stufe, eintrag] of Object.entries(istObjekt(config.reviewStufen) ? config.reviewStufen : {})) {
    if (!istObjekt(eintrag) || !Array.isArray(eintrag.rollen) || !Number.isInteger(eintrag.reviewer)) continue;
    if (eintrag.rollen.length !== eintrag.reviewer) {
      out.push(befund(`reviewStufen.${stufe}.rollen`, `nennt ${eintrag.rollen.length} Rollen, reviewer verlangt ${eintrag.reviewer}`));
    }
  }
  return out;
}

// SYNC: Laufzeitregel in kit/board.mjs, validatePairs — Namen aus reviewers, kein Autor prüft sich selbst.
function regelPaare(config) {
  const block = istObjekt(config.issueReview) ? config.issueReview : {};
  const bekannt = new Set((Array.isArray(block.reviewers) ? block.reviewers : []).map((r) => r?.name));
  const out = [];
  for (const [autor, genannt] of Object.entries(istObjekt(block.pairs) ? block.pairs : {})) {
    for (const name of Array.isArray(genannt) ? genannt : []) {
      const pfad = `issueReview.pairs.${autor}`;
      if (name === autor) out.push(befund(pfad, `nennt '${autor}' sich selbst — der Autor darf nicht sein eigener Prüfer sein`));
      else if (!bekannt.has(name)) out.push(befund(pfad, `'${name}' steht nicht in issueReview.reviewers`));
    }
  }
  return out;
}

// SYNC: Laufzeitregel in kit/checks.mjs, pruefeBereichsnamen — jedes areas steht in checkAreas.
function regelBereiche(config) {
  const bekannt = new Set(Object.keys(istObjekt(config.checkAreas) ? config.checkAreas : {}));
  const out = [];
  (Array.isArray(config.buildChecks) ? config.buildChecks : []).forEach((check, i) => {
    const fremd = (Array.isArray(check?.areas) ? check.areas : []).filter((name) => !bekannt.has(name));
    const genannt = fremd.map((n) => "'" + n + "'").join(", ");
    if (fremd.length > 0) out.push(befund(`buildChecks[${i}].areas`, `nennt ${genannt}, das nicht in checkAreas steht`));
  });
  return out;
}

/** Die Regeln über mehrere Felder, angewandt auf eine (gemischte) Konfiguration. */
export function zusatzregeln(config) {
  if (!istObjekt(config)) return [];
  return [...regelRollenzahl(config), ...regelPaare(config), ...regelBereiche(config)];
}

// ============================================================
// Themen (Plan #674 E14)
// ============================================================

/** Wurzelfeld → Thema. Ein Test verlangt jedes Wurzelfeld des Schemas außer `version`. */
export const THEMEN = {
  buildChecks: "Prüfungen", checkAreas: "Prüfungen", mutationCommand: "Prüfungen", formatFixCommand: "Prüfungen", spec: "Prüfungen",
  codeHost: "Board", issueTracker: "Board", provider: "Board", columns: "Board", github: "Board", toolbox: "Board", local: "Board",
  reviewScope: "Review", reviewModel: "Review", reviewCommand: "Review", issueReview: "Review", reviewStufen: "Review",
  night: "Nachtbetrieb",
  mainBranch: "Release", productionBranch: "Release", triggers: "Release",
};

// ============================================================
// Team- und persönliche Ebene (Plan #674 E6)
// ============================================================
//
// Die heruntergeladene Datei hat keine Nachbardatei board.mjs, aus der sie importieren
// könnte — darum eine dritte Kopie. test/workflow-config-merge.test.mjs hält alle drei gleich.

// SYNC: dieselbe Liste in kit/board.mjs und kit/night.mjs — Änderungen dort nachziehen.
const LOCAL_OVERRIDE_ALLOWLIST = ["reviewModel", "reviewCommand", "reviewScope", "triggers", "toolbox.tokenFile"];

// SYNC: dieselbe Zuordnung in kit/board.mjs und kit/night.mjs.
const REVIEWER_PAAR = { reviewModel: "reviewCommand", reviewCommand: "reviewModel" };

// SYNC: strukturgleich zu zerlegeAllowlist in kit/board.mjs und kit/night.mjs.
function zerlegeAllowlist(allowlist) {
  const erlaubteBlaetter = new Map();
  const erlaubteFelder = new Set();
  for (const pfad of allowlist) {
    const [kopf, blatt] = pfad.split(".");
    if (blatt) {
      if (!erlaubteBlaetter.has(kopf)) erlaubteBlaetter.set(kopf, new Set());
      erlaubteBlaetter.get(kopf).add(blatt);
    } else {
      erlaubteFelder.add(kopf);
    }
  }
  return { erlaubteFelder, erlaubteBlaetter };
}

// SYNC: strukturgleich zu setzePersoenlichesFeld in kit/board.mjs — beim Reviewer-Paar
// weicht das Gegenstück, sofern die persönliche Datei es nicht selbst nennt.
function setzePersoenlichesFeld(config, feld, wert, local) {
  config[feld] = wert;
  const gegenstueck = REVIEWER_PAAR[feld];
  if (gegenstueck && !(gegenstueck in local)) delete config[gegenstueck];
}

// SYNC: strukturgleich zu mergeWorkflowConfig in kit/board.mjs.
export function mergeWorkflowConfig(shared, local) {
  const config = { ...shared };
  const ignored = [];
  if (!local) return { config, ignored };
  const { erlaubteFelder, erlaubteBlaetter } = zerlegeAllowlist(LOCAL_OVERRIDE_ALLOWLIST);
  for (const [feld, wert] of Object.entries(local)) {
    if (erlaubteFelder.has(feld)) {
      setzePersoenlichesFeld(config, feld, wert, local);
    } else if (erlaubteBlaetter.has(feld) && istObjekt(wert)) {
      const blaetter = erlaubteBlaetter.get(feld);
      const zusammen = { ...config[feld] };
      for (const [unterfeld, unterwert] of Object.entries(wert)) {
        if (blaetter.has(unterfeld)) zusammen[unterfeld] = unterwert;
        else ignored.push(`${feld}.${unterfeld}`);
      }
      config[feld] = zusammen;
    } else {
      ignored.push(feld);
    }
  }
  return { config, ignored };
}

/** Ob ein Pfad persönlich abweichen darf. */
export function persoenlichErlaubt(pfad) {
  return LOCAL_OVERRIDE_ALLOWLIST.includes(pfad);
}

function lies(objekt, pfad) {
  return pfad.split(".").reduce((k, teil) => (istObjekt(k) ? k[teil] : undefined), objekt);
}

function setze(objekt, pfad, wert) {
  const teile = pfad.split(".");
  let k = objekt;
  for (const teil of teile.slice(0, -1)) {
    if (!istObjekt(k[teil])) k[teil] = {};
    k = k[teil];
  }
  k[teile.at(-1)] = wert;
}

function entferne(objekt, pfad) {
  const [kopf, blatt] = pfad.split(".");
  if (!blatt) return delete objekt[kopf];
  if (!istObjekt(objekt[kopf])) return;
  delete objekt[kopf][blatt];
  if (Object.keys(objekt[kopf]).length === 0) delete objekt[kopf];
}

/**
 * Je Einstellung Teamwert, persönliche Abweichung und geltender Wert. Schlüssel sind die
 * Wurzelfelder aus Schema, Team- und persönlicher Datei sowie die Blätter der Allowlist.
 */
export function ebenen(team, lokal) {
  const { config } = mergeWorkflowConfig(team ?? {}, lokal ?? null);
  const pfade = new Set([
    ...Object.keys(SCHEMA.properties ?? {}).filter((f) => f !== "version"),
    ...Object.keys(team ?? {}),
    ...Object.keys(lokal ?? {}).filter((f) => !f.includes(".") && !LOCAL_OVERRIDE_ALLOWLIST.some((p) => p.startsWith(`${f}.`))),
    ...LOCAL_OVERRIDE_ALLOWLIST,
  ]);
  const out = {};
  for (const pfad of pfade) {
    out[pfad] = { team: lies(team ?? {}, pfad), persoenlich: lies(lokal ?? {}, pfad), gilt: lies(config, pfad), persoenlichErlaubt: persoenlichErlaubt(pfad) };
  }
  return out;
}

const tiefeKopie = (w) => (w === undefined ? undefined : structuredClone(w));

/**
 * Wendet Änderungen auf der gewählten Ebene an. Liefert `{ ok: true, team, lokal }` mit
 * neuen Objekten oder `{ ok: false, grund }`. Persönlich geht nur, was die Allowlist
 * erlaubt; `entfernt` nimmt persönliche Abweichungen zurück, danach gilt der Teamwert.
 */
export function aenderungAnwenden(team, lokal, { ebene, aenderungen = [], entfernt = [] }) {
  const neuTeam = tiefeKopie(team ?? {});
  const neuLokal = tiefeKopie(lokal ?? {});
  if (ebene !== "team" && ebene !== "persoenlich") return { ok: false, grund: `Ebene '${ebene}' ist unbekannt — erlaubt sind team und persoenlich` };
  const ziel = ebene === "team" ? neuTeam : neuLokal;
  for (const { pfad, wert } of aenderungen) {
    if (ebene === "persoenlich" && !persoenlichErlaubt(pfad)) {
      return { ok: false, grund: `${pfad} gilt für das ganze Team und lässt sich nicht persönlich speichern` };
    }
    setze(ziel, pfad, tiefeKopie(wert));
  }
  for (const pfad of entfernt) entferne(neuLokal, pfad);
  return { ok: true, team: neuTeam, lokal: neuLokal };
}

/**
 * Prüft die gemischte Konfiguration: Schema und Regeln über mehrere Felder. `aenderungen`
 * werden vorher auf `ebene` angewandt — so trägt ein gespeicherter ungültiger Wert
 * denselben Grund wie eine Änderung auf ihn.
 */
export function pruefe(team, lokal, aenderungen = [], ebene = "team") {
  const angewandt = aenderungAnwenden(team, lokal, { ebene, aenderungen });
  if (!angewandt.ok) return [befund(aenderungen[0]?.pfad ?? "", angewandt.grund)];
  const { config } = mergeWorkflowConfig(angewandt.team, angewandt.lokal);
  return [...pruefeSchema(config), ...zusatzregeln(config)];
}

// ============================================================
// Schreiber mit minimalem Diff (Plan #674 E7)
// ============================================================
//
// JSON.stringify schriebe jede Datei neu formatiert; wer danach `git diff` liest, sähe eine
// umgebaute Datei statt der einen geänderten Zeile. Deshalb wird der Text zerlegt und nur an
// den Stellen ersetzt, deren Wert sich geändert hat. Einfache Werte behalten ihre Zeile, Listen
// und Objekte, die sich ändern, werden als ganzer Wertebereich neu geschrieben — elementweises
// Erhalten innerhalb einer Liste kostete einen Diff-Algorithmus ohne fachlichen Nutzen.

/** Leser über einem JSON-Text mit Positionszeiger. */
class JsonLeser {
  constructor(text) { this.text = text; this.i = 0; }

  leer() {
    while (/\s/.test(this.text[this.i] ?? "")) this.i++;
  }

  zeichenkette() {
    const start = this.i++;
    while (this.text[this.i] !== '"') this.i += this.text[this.i] === "\\" ? 2 : 1;
    this.i++;
    return { start, ende: this.i };
  }

  wert() {
    this.leer();
    const start = this.i;
    const zeichen = this.text[this.i];
    if (zeichen === "{") return this.objekt(start);
    if (zeichen === "[") return this.liste(start);
    if (zeichen === '"') return { typ: "wert", ...this.zeichenkette() };
    while (this.i < this.text.length && !/[\s,\]}]/.test(this.text[this.i])) this.i++;
    return { typ: "wert", start, ende: this.i };
  }

  /** Überspringt ein Komma samt Leerraum hinter einem Element. */
  trenner() {
    this.leer();
    if (this.text[this.i] === ",") this.i++;
    this.leer();
  }

  objekt(start) {
    this.i++;
    const glieder = [];
    this.leer();
    while (this.text[this.i] !== "}") {
      const schluessel = this.zeichenkette();
      this.leer();
      this.i++; // ':'
      const kind = this.wert();
      glieder.push({ name: JSON.parse(this.text.slice(schluessel.start, schluessel.ende)), start: schluessel.start, kind });
      this.trenner();
    }
    this.i++;
    return { typ: "objekt", start, ende: this.i, glieder };
  }

  liste(start) {
    this.i++;
    this.leer();
    while (this.text[this.i] !== "]") {
      this.wert();
      this.trenner();
    }
    this.i++;
    return { typ: "liste", start, ende: this.i };
  }
}

/** Zerlegt JSON in Knoten mit Positionen. Die Datei ist vorher mit JSON.parse geprüft. */
function zerlege(text) {
  return new JsonLeser(text).wert();
}

const gleich = (a, b) => JSON.stringify(a) === JSON.stringify(b);

/** Die Einrückung der Zeile, in der `pos` steht. */
function einrueckungAn(text, pos) {
  const zeilenanfang = text.lastIndexOf("\n", pos - 1) + 1;
  return text.slice(zeilenanfang).match(/^[ \t]*/)[0];
}

/** Die Einrückungseinheit der Datei: die erste eingerückte Zeile, sonst zwei Leerzeichen. */
function einheitVon(text) {
  return text.match(/\n([ \t]+)\S/)?.[1] ?? "  ";
}

function serialisiere(wert, einzug, einheit) {
  return JSON.stringify(wert, null, einheit).replaceAll("\n", `\n${einzug}`);
}

/** Die Ersetzungen für einen geänderten Wert an einem Glied. */
function wertAendern(text, glied, altWert, neuWert, einheit, out) {
  if (istObjekt(altWert) && istObjekt(neuWert) && glied.kind.typ === "objekt") {
    objektAendern(text, glied.kind, altWert, neuWert, einheit, out);
    return;
  }
  out.push({ start: glied.kind.start, ende: glied.kind.ende, text: serialisiere(neuWert, einrueckungAn(text, glied.start), einheit) });
}

/**
 * Entfernt zusammenhängende Läufe entfernter Glieder samt Komma. Steht nach einem Lauf ein
 * bleibendes Glied, reicht der Schnitt bis zu dessen Anfang; endet das Objekt mit dem Lauf,
 * beginnt er hinter dem letzten bleibenden Wert. So überlappen sich keine zwei Schnitte.
 */
function laeufeEntfernen(knoten, entfernt, out) {
  const g = knoten.glieder;
  let i = 0;
  while (i < g.length) {
    if (!entfernt.has(i)) { i++; continue; }
    let j = i;
    while (j + 1 < g.length && entfernt.has(j + 1)) j++;
    if (j + 1 < g.length) out.push({ start: g[i].start, ende: g[j + 1].start, text: "" });
    else out.push({ start: i > 0 ? g[i - 1].kind.ende : knoten.start + 1, ende: g[j].kind.ende, text: "" });
    i = j + 1;
  }
}

function gliederAnhaengen(text, knoten, neue, einheit, out) {
  if (neue.length === 0) return;
  const letztes = knoten.glieder.at(-1);
  if (letztes) {
    const einzug = einrueckungAn(text, letztes.start);
    const zeilen = neue.map(([name, w]) => `,\n${einzug}${JSON.stringify(name)}: ${serialisiere(w, einzug, einheit)}`).join("");
    out.push({ start: letztes.kind.ende, ende: letztes.kind.ende, text: zeilen });
    return;
  }
  const aussen = einrueckungAn(text, knoten.start);
  const einzug = aussen + einheit;
  const zeilen = neue.map(([name, w]) => `${einzug}${JSON.stringify(name)}: ${serialisiere(w, einzug, einheit)}`).join(",\n");
  out.push({ start: knoten.start + 1, ende: knoten.ende - 1, text: `\n${zeilen}\n${aussen}` });
}

function objektAendern(text, knoten, alt, neu, einheit, out) {
  const entfernt = new Set();
  knoten.glieder.forEach((glied, index) => {
    if (!(glied.name in neu)) entfernt.add(index);
    else if (!gleich(alt[glied.name], neu[glied.name])) wertAendern(text, glied, alt[glied.name], neu[glied.name], einheit, out);
  });
  const neue = Object.entries(neu).filter(([name]) => !(name in alt));
  const bleibend = knoten.glieder.filter((_, i) => !entfernt.has(i));
  if (bleibend.length === 0 && knoten.glieder.length > 0) {
    // Alles weg: den Innenraum ersetzen — leer, oder durch die neuen Glieder.
    if (neue.length === 0) out.push({ start: knoten.start + 1, ende: knoten.ende - 1, text: "" });
    else gliederAnhaengen(text, { ...knoten, glieder: [] }, neue, einheit, out);
    return;
  }
  laeufeEntfernen(knoten, entfernt, out);
  gliederAnhaengen(text, { ...knoten, glieder: bleibend }, neue, einheit, out);
}

/**
 * Schreibt `neu` in den JSON-Text `alt` und ändert dabei nur, was sich geändert hat.
 * Eine unveränderte Datei bleibt bytegleich.
 */
export function schreibeJson(alt, neu) {
  const altWert = JSON.parse(alt);
  if (gleich(altWert, neu)) return alt;
  const wurzel = zerlege(alt);
  const einheit = einheitVon(alt);
  const out = [];
  if (wurzel.typ === "objekt" && istObjekt(neu) && istObjekt(altWert)) {
    objektAendern(alt, wurzel, altWert, neu, einheit, out);
  } else {
    out.push({ start: wurzel.start, ende: wurzel.ende, text: JSON.stringify(neu, null, einheit) });
  }
  let text = alt;
  for (const e of out.sort((a, b) => b.start - a.start || b.ende - a.ende)) {
    text = text.slice(0, e.start) + e.text + text.slice(e.ende);
  }
  return text;
}

